interface Component {
  render(): string
}
class Leaf implements Component {
  render() { return 'leaf' }
}
class Node implements Component {
  children: Component[] = []
  render() { return this.children.map(c => c.render()).join('') }
}
function clientRender(c: Component) {
  // Client checks internals instead of using a uniform API
  if ((c as any).children) {
    (c as any).children.forEach(child => console.log(child.render()))
  } else {
    console.log(c.render())
  }
}

// Version A
interface Component { render(): string }
class Button implements Component { render() { return 'Button' } }
class Panel implements Component {
  children: Component[] = []
  add(c: Component) { this.children.push(c) }
  render() { return this.children.map(c => c.render()).join(',') }
}

// Version B
class Widget {
  children?: Widget[]
  render(): string {
    if (this.children && this.children.length) {
      return this.children.map(c => c.render()).join(',')
    }
    return 'Widget'
  }
}

function renderAll(items: (Component | Widget)[]) {
  items.forEach(i => {
    // Version B usage forces type checks
    if ((i as any).children) {
      (i as any).children.forEach((c: any) => console.log(c.render()))
    } else {
      console.log((i as any).render())
    }
  })
}
